import { NextRequest, NextResponse } from 'next/server'
import { getModeratorPassword, setModeratorSessionCookie } from '@/lib/moderator-session'
import { rateLimit } from '@/lib/rate-limit'
import { timingSafeEqual } from 'crypto'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function safeEqual(a: string, b: string): boolean {
  const A = Buffer.from(a)
  const B = Buffer.from(b)
  if (A.length !== B.length) return false
  return timingSafeEqual(A, B)
}

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (!rateLimit(`moderator-login:${ip}`, 5, 15 * 60 * 1000)) {
    return NextResponse.json({ error: 'Too many attempts. Wait 15 min.' }, { status: 429 })
  }

  const body = await req.json().catch(() => null)
  const password = String((body && (body as { password?: unknown }).password) ?? '')
  if (!password) return NextResponse.json({ error: 'Password required.' }, { status: 400 })

  let expected: string
  try {
    expected = getModeratorPassword()
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Server misconfigured.'
    return NextResponse.json({ error: msg }, { status: 500 })
  }

  if (!safeEqual(password, expected)) {
    return NextResponse.json({ error: 'Wrong password.' }, { status: 401 })
  }

  const res = NextResponse.json({ ok: true })
  setModeratorSessionCookie(res)
  return res
}

import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'
import { getSessionSecret } from '@/lib/session'

// Moderator session. Like the owner/admin panel, access is gated by a single
// MODERATOR_PASSWORD env var — there is no moderator user table (for the first
// 3 months the founders themselves are the moderator). Successful password
// check sets this cookie; every moderator endpoint verifies it. The HMAC is
// namespaced with `moderator:` so a consumer, farmer, rider, or admin token
// cannot be replayed against moderator routes — that is what keeps the
// /moderator area invisible to every other role.
const COOKIE_NAME = 'yff_moderator'
const TOKEN_TTL_MS = 7 * 24 * 60 * 60 * 1000

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(`moderator:${payload}`).digest())
}

export function getModeratorPassword(): string {
  const pw = process.env.MODERATOR_PASSWORD
  if (!pw || pw.length < 8) {
    throw new Error(
      'MODERATOR_PASSWORD env var is missing or too short. Set an 8+ char value in your environment.',
    )
  }
  return pw
}

// The single zone this moderator manages. Defaults to the launch zone.
export function getModeratorZone(): string {
  return process.env.MODERATOR_ZONE || 'tadepalligudem'
}

export function createModeratorSessionToken(): string {
  const issuedAt = Date.now()
  const payload = `moderator.${issuedAt}`
  return `${payload}.${sign(payload)}`
}

export function isModeratorRequest(req: NextRequest): boolean {
  const token = req.cookies.get(COOKIE_NAME)?.value
  if (!token) return false
  const parts = token.split('.')
  if (parts.length !== 3) return false
  const [marker, issuedAtStr, sig] = parts
  if (marker !== 'moderator') return false
  const issuedAt = Number(issuedAtStr)
  if (!Number.isFinite(issuedAt)) return false
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return false
  let expected: string
  try {
    expected = sign(`${marker}.${issuedAtStr}`)
  } catch {
    return false
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

export function setModeratorSessionCookie(res: NextResponse): void {
  const token = createModeratorSessionToken()
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearModeratorSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const MODERATOR_SESSION_COOKIE_NAME = COOKIE_NAME

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }

  const zone = getModeratorZone()
  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // All farmers in this zone — needed to scope orders/listings to the zone.
  const { data: zoneFarmers, error: fErr } = await supabase
    .from('farmers')
    .select('id, active')
    .eq('region_slug', zone)

  if (fErr) {
    console.error('[YFF moderator/stats] farmers query failed:', fErr.message)
    return NextResponse.json({ error: fErr.message }, { status: 500 })
  }

  const farmerIds = (zoneFarmers ?? []).map((f) => f.id)
  const activeFarmers = (zoneFarmers ?? []).filter((f) => f.active).length

  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()

  // Default everything that depends on having farmers in the zone.
  let ordersThisWeek = 0
  let gmvThisWeek = 0
  let consumers = 0
  let pendingApprovals = 0

  if (farmerIds.length > 0) {
    // Orders this week (count) + GMV this week (sum of total_price).
    const { data: weekOrders } = await supabase
      .from('orders')
      .select('total_price')
      .in('farmer_id', farmerIds)
      .gte('created_at', weekAgo)
    ordersThisWeek = weekOrders?.length ?? 0
    gmvThisWeek = (weekOrders ?? []).reduce((sum, o) => sum + Number(o.total_price ?? 0), 0)

    // Consumers = distinct buyers who have ever ordered from a zone farmer.
    const { data: buyerRows } = await supabase
      .from('orders')
      .select('consumer_id')
      .in('farmer_id', farmerIds)
      .not('consumer_id', 'is', null)
    consumers = new Set((buyerRows ?? []).map((r) => r.consumer_id)).size

    // Pending approvals: listings awaiting review. The listing-approval flow
    // (Feature 3) is not built yet, so this is 0 until a 'pending_review'
    // status exists — counting it here keeps the card correct once it ships.
    const { count: pendingCount } = await supabase
      .from('produce_listings')
      .select('id', { count: 'exact', head: true })
      .in('farmer_id', farmerIds)
      .eq('status', 'pending_review')
    pendingApprovals = pendingCount ?? 0
  }

  // Open escalations: the escalations table (Feature 7) does not exist yet.
  const openEscalations = 0

  return NextResponse.json({
    zone,
    stats: {
      activeFarmers,
      consumers,
      ordersThisWeek,
      gmvThisWeek,
      openEscalations,
      pendingApprovals,
    },
  })
}

'use client'

import { useRouter, usePathname } from 'next/navigation'
import { useEffect, useState, type ReactNode } from 'react'

type NavItem = { label: string; href: string; ready: boolean }

// The 9 sections from the spec. Only the ones built so far route anywhere;
// the rest are shown greyed with a "soon" tag so the full shape is visible.
const NAV: NavItem[] = [
  { label: 'Dashboard', href: '/moderator', ready: true },
  { label: 'Farmer onboarding', href: '/moderator/farmers', ready: true },
  { label: 'Listings', href: '/moderator/listings', ready: false },
  { label: 'Supply & demand', href: '/moderator/supply', ready: false },
  { label: 'Consumers', href: '/moderator/consumers', ready: false },
  { label: 'Delivery agents', href: '/moderator/agents', ready: false },
  { label: 'Escalations', href: '/moderator/escalations', ready: false },
  { label: 'Price management', href: '/moderator/prices', ready: false },
  { label: 'Reports', href: '/moderator/reports', ready: false },
]

export default function ModeratorShell({
  title,
  subtitle,
  zone,
  children,
}: {
  title: string
  subtitle?: string
  zone: string
  children: ReactNode
}) {
  const router = useRouter()
  const pathname = usePathname()
  const [menuOpen, setMenuOpen] = useState(false)

  const logout = async () => {
    await fetch('/api/moderator/logout', { method: 'POST', credentials: 'same-origin' }).catch(() => null)
    router.replace('/moderator/login')
  }

  const zoneLabel = zone.charAt(0).toUpperCase() + zone.slice(1)

  return (
    <div className="min-h-screen bg-gray-50 flex">
      {/* Sidebar */}
      <aside
        className={`fixed md:static z-30 inset-y-0 left-0 w-60 bg-green-950 text-green-50 flex-col transition-transform ${
          menuOpen ? 'flex translate-x-0' : 'hidden md:flex md:translate-x-0'
        }`}
      >
        <div className="px-5 pt-6 pb-5 border-b border-green-900/60">
          <p className="text-lg font-extrabold tracking-tight text-white">GoGrameen</p>
          <p className="text-[11px] text-green-300/80">Moderator · {zoneLabel}</p>
        </div>
        <nav className="flex-1 py-3">
          {NAV.map((item) => {
            const active = pathname === item.href
            if (!item.ready) {
              return (
                <div
                  key={item.href}
                  className="flex items-center justify-between px-5 py-2.5 text-sm text-green-300/40 cursor-not-allowed"
                >
                  <span>{item.label}</span>
                  <span className="text-[9px] uppercase bg-green-900/50 px-1.5 py-0.5 rounded">soon</span>
                </div>
              )
            }
            return (
              <button
                key={item.href}
                onClick={() => { setMenuOpen(false); router.push(item.href) }}
                className={`w-full text-left px-5 py-2.5 text-sm transition-colors ${
                  active ? 'bg-green-800 text-white font-semibold border-l-4 border-green-300' : 'text-green-100 hover:bg-green-900/60'
                }`}
              >
                {item.label}
              </button>
            )
          })}
        </nav>
        <button onClick={logout} className="px-5 py-4 text-xs text-green-300 hover:text-white text-left border-t border-green-900/60">
          Log out
        </button>
      </aside>

      {menuOpen && (
        <div className="fixed inset-0 bg-black/40 z-20 md:hidden" onClick={() => setMenuOpen(false)} />
      )}

      {/* Main */}
      <div className="flex-1 min-w-0">
        <header className="bg-white border-b border-gray-100 px-4 md:px-8 py-4 flex items-center justify-between gap-3">
          <div className="flex items-center gap-3 min-w-0">
            <button onClick={() => setMenuOpen(true)} className="md:hidden text-gray-700 text-xl leading-none">☰</button>
            <div className="min-w-0">
              <h1 className="text-lg md:text-xl font-extrabold text-gray-900 leading-tight truncate">{title}</h1>
              {subtitle && <p className="text-xs text-gray-500 truncate">{subtitle}</p>}
            </div>
          </div>
          <span className="text-[11px] font-semibold bg-green-100 text-green-800 px-3 py-1 rounded-full whitespace-nowrap">
            {zoneLabel} zone
          </span>
        </header>
        <main className="p-4 md:p-8 max-w-5xl">{children}</main>
      </div>
    </div>
  )
}

// Shared client-side auth guard. Returns the zone once confirmed, or redirects
// to /moderator/login. Every moderator page uses this so a farmer / consumer /
// rider who lands on a /moderator URL is bounced out immediately.
export function useModeratorAuth() {
  const router = useRouter()
  const [zone, setZone] = useState<string | null>(null)
  const [checked, setChecked] = useState(false)

  useEffect(() => {
    let cancelled = false
    fetch('/api/moderator/me', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return
        if (json?.moderator) { setZone(json.zone); setChecked(true) }
        else router.replace('/moderator/login')
      })
      .catch(() => { if (!cancelled) router.replace('/moderator/login') })
    return () => { cancelled = true }
  }, [router])

  return { zone, checked }
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from './ModeratorShell'

type Stats = {
  activeFarmers: number
  consumers: number
  ordersThisWeek: number
  gmvThisWeek: number
  openEscalations: number
  pendingApprovals: number
}

export default function ModeratorDashboard() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [stats, setStats] = useState<Stats | null>(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!checked) return
    fetch('/api/moderator/stats', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (json?.stats) setStats(json.stats)
        else setError(json?.error ?? 'Could not load stats.')
      })
      .catch(() => setError('Network error.'))
  }, [checked])

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const today = new Date().toLocaleDateString('en-IN', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  })

  const hasAlerts = (stats?.openEscalations ?? 0) > 0 || (stats?.pendingApprovals ?? 0) > 0

  return (
    <ModeratorShell title="Dashboard" subtitle={today} zone={zone}>
      {/* Alert strip */}
      {stats && (
        hasAlerts ? (
          <div className="bg-amber-50 border border-amber-200 text-amber-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ⚠ {stats.pendingApprovals > 0 && `${stats.pendingApprovals} listing${stats.pendingApprovals > 1 ? 's' : ''} pending approval`}
            {stats.pendingApprovals > 0 && stats.openEscalations > 0 && ' · '}
            {stats.openEscalations > 0 && `${stats.openEscalations} open escalation${stats.openEscalations > 1 ? 's' : ''} need attention`}
          </div>
        ) : (
          <div className="bg-green-50 border border-green-200 text-green-800 rounded-xl px-4 py-3 text-sm font-semibold mb-5">
            ✓ All clear — no pending approvals or open escalations
          </div>
        )
      )}

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-3 text-sm font-semibold mb-5">{error}</div>
      )}

      {/* Stat cards */}
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 md:gap-4">
        <StatCard label="Active farmers" value={stats?.activeFarmers} />
        <StatCard label="Consumers" value={stats?.consumers} />
        <StatCard label="Orders this week" value={stats?.ordersThisWeek} />
        <StatCard label="GMV this week" value={stats ? `₹${stats.gmvThisWeek.toLocaleString('en-IN')}` : undefined} />
        <StatCard label="Open escalations" value={stats?.openEscalations} tone={(stats?.openEscalations ?? 0) > 0 ? 'red' : undefined} hint="Coming soon" />
        <StatCard label="Pending approvals" value={stats?.pendingApprovals} tone={(stats?.pendingApprovals ?? 0) > 0 ? 'amber' : undefined} hint="Coming soon" />
      </div>

      {/* Quick actions */}
      <div className="mt-7">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide mb-2">Quick actions</p>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => router.push('/moderator/farmers/new')}
            className="bg-green-800 text-white text-sm font-bold px-4 py-2.5 rounded-xl active:bg-green-900"
          >
            + Onboard a farmer
          </button>
          <button
            onClick={() => router.push('/moderator/farmers')}
            className="bg-white border border-gray-200 text-gray-700 text-sm font-bold px-4 py-2.5 rounded-xl active:bg-gray-50"
          >
            View farmers
          </button>
        </div>
      </div>
    </ModeratorShell>
  )
}

function StatCard({
  label, value, tone, hint,
}: { label: string; value?: number | string; tone?: 'red' | 'amber'; hint?: string }) {
  const valueColor = tone === 'red' ? 'text-red-600' : tone === 'amber' ? 'text-amber-600' : 'text-gray-900'
  return (
    <div className="bg-white rounded-2xl border border-gray-100 p-4 shadow-sm">
      <p className={`text-2xl md:text-3xl font-extrabold ${valueColor}`}>
        {value === undefined ? '—' : value}
      </p>
      <p className="text-xs text-gray-500 mt-1 font-medium">{label}</p>
      {hint && <p className="text-[10px] text-gray-300 mt-0.5">{hint}</p>}
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const METHODS = ['natural', 'low_chemical', 'chemical'] as const

function slugify(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// GET — all farmers in the moderator's zone, with a live listing count.
export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const { data: farmers, error } = await supabase
    .from('farmers')
    .select('id, slug, name, village, district, method, phone, active, created_at')
    .eq('region_slug', zone)
    .order('created_at', { ascending: false })

  if (error) {
    console.error('[YFF moderator/farmers] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Listing count per farmer (one grouped query, merged in JS).
  const ids = (farmers ?? []).map((f) => f.id)
  const counts: Record<string, number> = {}
  if (ids.length > 0) {
    const { data: listings } = await supabase
      .from('produce_listings')
      .select('farmer_id')
      .in('farmer_id', ids)
    for (const l of listings ?? []) {
      if (l.farmer_id) counts[l.farmer_id] = (counts[l.farmer_id] ?? 0) + 1
    }
  }

  const withCounts = (farmers ?? []).map((f) => ({ ...f, listing_count: counts[f.id] ?? 0 }))
  return NextResponse.json({ farmers: withCounts })
}

// POST — register a new farmer in the zone. Auto-generates a unique slug.
export async function POST(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })

  const name = String((body as { name?: unknown }).name ?? '').trim()
  const phone = String((body as { phone?: unknown }).phone ?? '').trim()
  const village = String((body as { village?: unknown }).village ?? '').trim()
  const district = String((body as { district?: unknown }).district ?? '').trim()
  const methodRaw = String((body as { method?: unknown }).method ?? 'natural').trim()
  const story_quote = String((body as { story_quote?: unknown }).story_quote ?? '').trim()
  const farm_size_acres = Number((body as { farm_size_acres?: unknown }).farm_size_acres ?? 0) || null
  const farming_since_year = Number((body as { farming_since_year?: unknown }).farming_since_year ?? 0) || null

  if (!name) return NextResponse.json({ error: 'Name is required.' }, { status: 400 })
  const method = (METHODS as readonly string[]).includes(methodRaw) ? methodRaw : 'natural'

  // Unique slug — append -2, -3, ... if taken.
  const base = slugify(name) || 'farmer'
  let slug = base
  for (let i = 2; i < 50; i++) {
    const { data: existing } = await supabase.from('farmers').select('id').eq('slug', slug).maybeSingle()
    if (!existing) break
    slug = `${base}-${i}`
  }

  const { data: inserted, error } = await supabase
    .from('farmers')
    .insert({
      slug,
      name,
      phone: phone || null,
      village: village || null,
      district: district || null,
      method,
      story_quote: story_quote || null,
      farm_size_acres,
      farming_since_year,
      region_slug: zone,
      active: true,
    })
    .select('id, slug, name, phone')
    .single()

  if (error) {
    console.error('[YFF moderator/farmers] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  return NextResponse.json({ farmer: inserted })
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Farmer = {
  id: string
  slug: string
  name: string
  village: string | null
  district: string | null
  method: string | null
  phone: string | null
  active: boolean
  listing_count: number
}

const METHOD_LABEL: Record<string, string> = {
  natural: 'Natural',
  low_chemical: 'Low chem',
  chemical: 'Chemical',
}

export default function ModeratorFarmersPage() {
  const router = useRouter()
  const { zone, checked } = useModeratorAuth()
  const [farmers, setFarmers] = useState<Farmer[]>([])
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const load = useCallback(async () => {
    const r = await fetch('/api/moderator/farmers', { credentials: 'same-origin' }).catch(() => null)
    setLoading(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load farmers.'); return }
    setFarmers((json.farmers ?? []) as Farmer[])
  }, [])

  useEffect(() => { if (checked) void load() }, [checked, load])

  const toggleActive = async (f: Farmer) => {
    if (busyId) return
    setBusyId(f.id)
    const r = await fetch(`/api/moderator/farmers/${f.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ active: !f.active }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) { setError('Update failed.'); return }
    setFarmers((list) => list.map((x) => (x.id === f.id ? { ...x, active: !x.active } : x)))
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const activeCount = farmers.filter((f) => f.active).length

  return (
    <ModeratorShell title="Farmer onboarding" subtitle="Register a new farmer or manage existing ones" zone={zone}>
      <div className="flex items-center justify-between mb-4">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide">
          {activeCount} active farmer{activeCount !== 1 ? 's' : ''} in zone
        </p>
        <button
          onClick={() => router.push('/moderator/farmers/new')}
          className="bg-green-800 text-white text-sm font-bold px-4 py-2 rounded-xl active:bg-green-900"
        >
          + Add new farmer
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-2 text-sm font-semibold mb-4">{error}</div>
      )}

      {loading ? (
        <p className="text-sm text-gray-400 py-10 text-center">Loading…</p>
